      "content": "ALAPLE CSOMAG NEO\nSULY\nALAPANYAGOK\n30\nkg\nmarha gombcsont\n20\nkg\ncsirke farhat\n20\nkg\ncsirke lab\n75\ng\nfeherbors\n15\ndb\ncsillaganizs\n45\ndb\nfekete kardamom\n75\ndb\nszaritott shiitake\nSUM 70 kg\ncsomaghoz.\nSULY\nALAPANYAGOK\n2\nkg\nmarha gombcsont\n1\nkg\nfarhat\n1\nkg\ncsirke lab\n5\ng\nfeherbors\n1\ndb\ncsillaganizs\n3\ndb\nfekete kardamom\n5\ndb\nszaritott shiitake\nMegjegyzések:\nhetente\nGombcsont Eco-Meat. SMS-ben rendel. [phone redacted] 22 Kedden és Pénteken szállít.\nCSillagnazizs : 1kg a rendelés\nBoen Duna Panda\nAisa Gasztro : innen lehet még rendelni de drága Fekete Cardamon: ½ kilo 2 hétre.\nDuna Panda / Asia Gasztro Műveletek:\nKülön külön forrázom, mosom. Azta összerakom egy zacsiba.Fagyasztom.\nA marha csontot tedd fel hideg vizben, es forrald fel a vizet, amint felforrt, hagyd meg foni 2-3 percet, majd hideg viz alatt oblitsd le.\nA csirke farhatat es labat szinten ugyanigy blansirozd le.\nMerd ossze a csontokat es a fuszereket egy vakuum zsakba, es alacsony vakuumon csomagold el, majd fagyasztva tarold.",
      "hungarianNotes": "ALAPLE CSOMAG NEO\nSULY\nALAPANYAGOK\n30\nkg\nmarha gombcsont\n20\nkg\ncsirke farhat\n20\nkg\ncsirke lab\n75\ng\nfeherbors\n15\ndb\ncsillaganizs\n45\ndb\nfekete kardamom\n75\ndb\nszaritott shiitake\nSUM 70 kg\ncsomaghoz.\nSULY\nALAPANYAGOK\n2\nkg\nmarha gombcsont\n1\nkg\nfarhat\n1\nkg\ncsirke lab\n5\ng\nfeherbors\n1\ndb\ncsillaganizs\n3\ndb\nfekete kardamom\n5\ndb\nszaritott shiitake\nMegjegyzések:\nhetente\nGombcsont Eco-Meat. SMS-ben rendel. [phone redacted] 22 Kedden és Pénteken szállít.\nCSillagnazizs : 1kg a rendelés\nBoen Duna Panda\nAisa Gasztro : innen lehet még rendelni de drága Fekete Cardamon: ½ kilo 2 hétre.\nDuna Panda / Asia Gasztro Műveletek:\nKülön külön forrázom, mosom. Azta összerakom egy zacsiba.Fagyasztom.\nA marha csontot tedd fel hideg vizben, es forrald fel a vizet, amint felforrt, hagyd meg foni 2-3 percet, majd hideg viz alatt oblitsd le.\nA csirke farhatat es labat szinten ugyanigy blansirozd le.\nMerd ossze a csontokat es a fuszereket egy vakuum zsakba, es alacsony vakuumon csomagold el, majd fagyasztva tarold.",
