      "content": "CSIRKE SZÓSZ\nCsirke szósz\nsúly 8X\nalapanyag\n40\nL\nAlaplé\n14.4\nkg\nJapán szójaszósz\n8.4\nkg\nMirin\n3.1\nkg\ncukor\n6\nkg\nCsirke zsír\n0.5\nkg\nmsg\n8\nl\nalaplé\n2.2\nkg\nkukorica keményitő\nMegjegyzések:\nMSG:PanAsia vagy Asia Gasztro 1 zsák 22,3 kg MSG = AJI-NO-MOTO Mononatriumglutamat\n2 hetente 1 adag. Erőlevessel a zöldséges fagysztóban van.\na Tigrisnek 5 és 10 zacskü kell hetente. A bisztro heti 5 zacskot hasznal. Kukorica keményítő békás: 25 kilonként vesszük.\nMűveletek:\nIde sült csirkezsír kell. Ha nincs akkor jó a szűz.\n/ Az alaplevet, a szójaszószt, a mirint, az msgt, a csirkezsírt és a cukrot forrald fel.\n/Sűrítsd be egy kukoricalisztes alapleves mixxel ami a recept also felen szerepel. A keményítőhöz hideg legyen az alaplé.\n/Sűrítés után forralom egy kicsit 15 percet, hogy ne legyen keményítő íze. utána GN és hűtő vagy sokkoló.\n2 Sokkold le 3c fokra majd 2.5kgnként vákuumozd le. Sokkolva fagyaszd a vákuum zsákokat. Fagyasztva 6 hónapig tárolható. Ha nem fagyasztod le akkor használd fel 5 napon belül.\nKiolvasztva 3 napon belül el kell használni.",
