      "content": "MÁLNÁS MOONCAKE\nALAP\nsuly\nalapanyag\n600\ng\nfehércsoki\n500\ng\nvaj\n850\ng\ncukor\n12\ndb\ntojas\n50\ng\ntejpor\n120\ng\nmálnapor -lioflizált\nmálnából\n150\ng\nmandula liszt\n200\ng\ndarált banán\n450\ng\nsimaliszt bl 55 finomliszt\n20\ng\nmalnapiros festek\nMegjegyzések:\nfehércsoki,tejpor,lioflizált málnából,mandula liszt banán- pilpel\nmalnapiros festek - metro Műveletek:\nHozzáadási sorrend a dagasztóba: 1.tojásos cukor, 2. száraz anyagok, 3. vajas csoki keverés. 4. banán 5. ételfesték.\nA málnaporhoz a liofilizált málnát a vitamixben porítsd le teljesen, majd szitáld át hogy ne maradjon benne mag. Ezt a már kész átszitált port mérd a recepthez. 150g porhoz nagyjából 200g liofilizált málnára van szükséged.\nA fehércsokit és a vajat olvaszd össze gőz fölött.\nA cukrot és a tojást verd fel a keverőgépben a habverő fejjel, ellenőrizd, hogy a cukor feloldódjon, ha szükséges akkor porítsd a thermoban a cukrot mielőtt felhasználod. Add hozzá a banán pürét.\nAz olvadt csokis vajas mixet adagold a tojásos cukros mixhez és alaposan keverd el.\nAdd hozzá a tejport, málna port és a lisztet majd keverd el.\nEgy sütőpapírral bélelt 1/1-es tepsibe egyengesd el, rakj egy sütőpapírt a tetejére és süsd 130c-on 50 percig. 40% gőz. Csak sütés!\n8 Hűtsd le a sokkolóban 30 percre.\n8 Vedd ki és kesztyűs kézzel alaposan gyúrd át amíg egy homogén tésztát nem kapsz.\n9 Dobozold be.",
      "hungarianNotes": "MÁLNÁS MOONCAKE\nALAP\nsuly\nalapanyag\n600\ng\nfehércsoki\n500\ng\nvaj\n850\ng\ncukor\n12\ndb\ntojas\n50\ng\ntejpor\n120\ng\nmálnapor -lioflizált\nmálnából\n150\ng\nmandula liszt\n200\ng\ndarált banán\n450\ng\nsimaliszt bl 55 finomliszt\n20\ng\nmalnapiros festek\nMegjegyzések:\nfehércsoki,tejpor,lioflizált málnából,mandula liszt banán- pilpel\nmalnapiros festek - metro Műveletek:\nHozzáadási sorrend a dagasztóba: 1.tojásos cukor, 2. száraz anyagok, 3. vajas csoki keverés. 4. banán 5. ételfesték.\nA málnaporhoz a liofilizált málnát a vitamixben porítsd le teljesen, majd szitáld át hogy ne maradjon benne mag. Ezt a már kész átszitált port mérd a recepthez. 150g porhoz nagyjából 200g liofilizált málnára van szükséged.\nA fehércsokit és a vajat olvaszd össze gőz fölött.\nA cukrot és a tojást verd fel a keverőgépben a habverő fejjel, ellenőrizd, hogy a cukor feloldódjon, ha szükséges akkor porítsd a thermoban a cukrot mielőtt felhasználod. Add hozzá a banán pürét.\nAz olvadt csokis vajas mixet adagold a tojásos cukros mixhez és alaposan keverd el.\nAdd hozzá a tejport, málna port és a lisztet majd keverd el.\nEgy sütőpapírral bélelt 1/1-es tepsibe egyengesd el, rakj egy sütőpapírt a tetejére és süsd 130c-on 50 percig. 40% gőz. Csak sütés!\n8 Hűtsd le a sokkolóban 30 percre.\n8 Vedd ki és kesztyűs kézzel alaposan gyúrd át amíg egy homogén tésztát nem kapsz.\n9 Dobozold be.",
