      "content": "SHOKUPAN (KENYÉR)\nsuly\nalapanyag\n2.5\nkg\nRétesliszt\n333\ng\nTejpor\n20\ng\nSó\n5\ng\nglutén\n240\ng\nCukor\n25\ng\nFriss élesztő\n800\ng\nViz (hideg)\n185\ng\nOlaj\n1200\ng\nTangzhong (hideg)\nMeleg vízben(max 40 fok) oldd fel a cukrot, majd morzsold bele az élesztőt, és keverd el alaposan. 15 percet áll.\nAmeddig áll addig mérd ki a szárazárut(liszt, só, kínai sütópor, buzasiker) és tedd bele a dagasztóba. Ezt be kell kapcsolni. Gyors fokozaton.\nAmeddig kavarog, addig mérd rá az olajat a cukros élesztős vízre.\nMérd ki a tangzhong külön edénybe.\nA gépbe add hozzá a folyadékokat. Előszor a cukros élesztős vizet, majd a tangzhong -ot.\nHagyd menni a gépet 15 percig. Tésztagyúrás.\nFedd le es a gepben pihentesd 20 percet. Tegyél rá nedves konyharuhát.\nPorciozd 370g-os bucikra és virgold be olajos felületen, majd hagyd kelni 30-50 percet 30C-on. Gyakorlat szerint letakarva van az asztalon.\nA megkelt bucikat nyújtsd ki egy 15cm széles 50cm hosszú formába, hajtsd fel a hosszabbik oldalan a szeleket majd teker fel a rovidebb oldalról mint egy palacsintát, hogy egy vastag de keskeny csigát kapj ami kozepen kisse keskenyebb.\n4db 1/3-os 150mm mely GN formát enyhén olajozz ki, és tegyél bele egy sütőpapírt úgy, hogy a hosszabbik oldalon átlógjon a sütőpapír.\nHelyezz a kibélelt GN-be 4db csiga alakba virgol bucit szorosan egymás mellé úgy, hogy a csigák spirál nézeti felülete a GN edény hosszabbik oldala felé nézzen (mint a képen)\nHelyezd a formákat a kelesztőbe 30c-on és 50% pára és keleszd 60 percet. (közben folyamatosan ellenőrizd, neha sokkal elobb megkel, van amikor tobb idore van szuksege)\nsutes: 180c 10perc 50%-os paratartalom=> 170c 20%para 30perc\nHagyd szobahomersekleture hulni 1 ora alatt majd csomagold folpackba, ha szukseges egy kisebb idore rakd a hutobe, hogy konnyebb legyen szeletelni, sutes utan 2 oraig ne szeleteld mert osszeugrik a belseje es szalonnas lesz.\nHa szobahomersekletu a kenyeret vagd 1.7cm vastag szeletekre\nDumpling",
      "hungarianNotes": "SHOKUPAN (KENYÉR)\nsuly\nalapanyag\n2.5\nkg\nRétesliszt\n333\ng\nTejpor\n20\ng\nSó\n5\ng\nglutén\n240\ng\nCukor\n25\ng\nFriss élesztő\n800\ng\nViz (hideg)\n185\ng\nOlaj\n1200\ng\nTangzhong (hideg)\nMeleg vízben(max 40 fok) oldd fel a cukrot, majd morzsold bele az élesztőt, és keverd el alaposan. 15 percet áll.\nAmeddig áll addig mérd ki a szárazárut(liszt, só, kínai sütópor, buzasiker) és tedd bele a dagasztóba. Ezt be kell kapcsolni. Gyors fokozaton.\nAmeddig kavarog, addig mérd rá az olajat a cukros élesztős vízre.\nMérd ki a tangzhong külön edénybe.\nA gépbe add hozzá a folyadékokat. Előszor a cukros élesztős vizet, majd a tangzhong -ot.\nHagyd menni a gépet 15 percig. Tésztagyúrás.\nFedd le es a gepben pihentesd 20 percet. Tegyél rá nedves konyharuhát.\nPorciozd 370g-os bucikra és virgold be olajos felületen, majd hagyd kelni 30-50 percet 30C-on. Gyakorlat szerint letakarva van az asztalon.\nA megkelt bucikat nyújtsd ki egy 15cm széles 50cm hosszú formába, hajtsd fel a hosszabbik oldalan a szeleket majd teker fel a rovidebb oldalról mint egy palacsintát, hogy egy vastag de keskeny csigát kapj ami kozepen kisse keskenyebb.\n4db 1/3-os 150mm mely GN formát enyhén olajozz ki, és tegyél bele egy sütőpapírt úgy, hogy a hosszabbik oldalon átlógjon a sütőpapír.\nHelyezz a kibélelt GN-be 4db csiga alakba virgol bucit szorosan egymás mellé úgy, hogy a csigák spirál nézeti felülete a GN edény hosszabbik oldala felé nézzen (mint a képen)\nHelyezd a formákat a kelesztőbe 30c-on és 50% pára és keleszd 60 percet. (közben folyamatosan ellenőrizd, neha sokkal elobb megkel, van amikor tobb idore van szuksege)\nsutes: 180c 10perc 50%-os paratartalom=> 170c 20%para 30perc\nHagyd szobahomersekleture hulni 1 ora alatt majd csomagold folpackba, ha szukseges egy kisebb idore rakd a hutobe, hogy konnyebb legyen szeletelni, sutes utan 2 oraig ne szeleteld mert osszeugrik a belseje es szalonnas lesz.\nHa szobahomersekletu a kenyeret vagd 1.7cm vastag szeletekre\nDumpling",
