        "Ha megvagy a rizzsel akkor merd ki a kemenyitot, nem art ha kicsit tobbet mersz belole. Helyezd egy sutopapirral belelt talcara, es rakd a sutobe, a legalacsonyabb legkeringtetesen 15 percre 150c-ra, es sterilizald.",
        "Vegyel 8db tiszta, mosott konyharuhat, es rakd oket egy 15l-es fazekba, ontsd fel vizzel, ugy hogy ellepje a konyharuhakat, majd forrald fel, es fozd a konyharuhat 5-10 percig, hogy sterilizald azt is. Egy csipesszel szedd at egy frissen mosott talcara es hideg vizzel mosd at, mjad csavard ki oket.",
        "A kemenyitot, nagyon ovatosan lassu mozdulatokkal keverd el a kojival, es lassan adagolva alaposan keverd el a rizzsel. Igyekezz tenyleg elkepesztoen alaposan atkeverni a kojit a rizzsel, kulonben nem fog noni rajta normalisan a koji. Ha nincs eleg hely a mely talcadban, akkor aranyosan oszd annyi fele a kojit olyan aranyban, mint ahogy a Riceed van.",
