        "A parakontroller PID paraerzekelojet erositsd fel egy ragaccsal a kozepso talca melle a regal fuggoleges rudjara, ugy, hogy befele nezzen a regal belseje fele.",
        "A homersekleti pid kontroller homerojet pedig szurd be a kozepso talcaba a Rice kozepebe, es takargasd vissza a konyharuhaval.",
        "A regalt tekerd korbe ket retegben folpackkal, ugy, hogy a parasito kabele, es a radiator kabele kinnt maradjon, es ugyelj, hogy az erzekelok ne mozduljanak el.",
        "A radiatort dugd ossze a homersekleti PID-el, a paraerzekelobe pedig dugd be a parasito gepet.",
        "A homersekletet allitsd be 30c-ra PID kijelzojen, a paratartalmat pedig 85%-ra a masik PID kijelzojen.",
        "Ellenorizd a parasaitot, hogy megfeleloen mukodik e, majd nezd meg a radiatort, hogy a futes megy e rajta.",
        "Allitsd egy stabil homersekletu helyre, ahol viszonylag kicsit a legmozgas.",
        "Allits egy idozitot 24 orara, es hagyd inkubalodni a Ricet."
